head.script:
scwin.gVar = {
    "cUserData1" : ""
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = function () {
    // 기존 target(alias) 삭제 후 원본 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof ldl_org !== 'undefined') {
        $p.data.remove("ldl_org");
    }

    if (typeof gdl_org !== 'undefined') {
        $p.data.remove("gdl_org");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }   

    if (typeof gridView2 !== 'undefined') {
        gridView2.remove();
    }     

    // 조건 설정       
    let properties = {
        userData1: scwin.gVar["cUserData1"],
    };

    let cList = $c.gcm.createCList(properties);       

    // alias 원본 linkedDataList 생성 (gdl_org 기반)
    $c.gcm.createOrginalDataList();
    $c.gcm.createBasicLinkedDataList('', '', 'ldl_org');

    // target 생성 (aliasLinkedDataList : scope 속성에 원본 linkedDataList ID 지정)
    let strTarget = '<w2:aliasLinkedDataList ' + $c.gcm.getNameSpace() + ' ' + cList + ' id="target1" scope="ldl_org"></w2:aliasLinkedDataList>';
    $p.data.create(strTarget);

    // gridView 생성 (gridView1 : gdl_org, gridView2 : target1)
    $c.gcm.createOriginalGridView();
    $c.gcm.createLinkedGridView();
}
